import hashlib, json
from collections import Counter
from datetime import datetime
from pathlib import Path
for name in ('regras.md', 'eventos.json'):
    print('SHA256', name, hashlib.sha256(Path(name).read_bytes()).hexdigest())
events = json.loads(Path('eventos.json').read_text())
unique = {}
for event in events:
    key = event['event_id']
    if key in unique:
        assert unique[key] == event, f'Duplicata conflitante: {key}'
    else:
        unique[key] = event
start = datetime.fromisoformat('2026-10-10T00:00:00+00:00')
end = datetime.fromisoformat('2026-10-11T00:00:00+00:00')
def instant(event):
    return datetime.fromisoformat(event['em'].replace('Z', '+00:00'))
payments = [event for event in unique.values() if event['tipo'] == 'pago' and event['moeda'] == 'BRL' and start <= instant(event) < end]
channels = {'loja': 0, 'web': 0}
for payment in payments:
    refunds = [event for event in unique.values() if event['pedido'] == payment['pedido'] and event['tipo'] == 'estorno_confirmado' and instant(event) < end]
    net = payment['valor'] - sum(event['valor'] for event in refunds)
    channels[payment['canal']] += net
    print('PEDIDO', payment['pedido'], 'BRUTO', payment['valor'], 'ESTORNOS', [event['event_id'] for event in refunds], 'LIQUIDO', net, 'CANAL', payment['canal'])
print('REGISTROS', len(events), 'EVENTOS_UNICOS', len(unique), 'DUPLICATAS', {key: count - 1 for key, count in Counter(event['event_id'] for event in events).items() if count > 1})
print(json.dumps({'pedidos_incluidos': sorted(payment['pedido'] for payment in payments), 'receita_liquida_centavos': sum(channels.values()), 'por_canal_centavos': channels}, ensure_ascii=False))
