assert type(answer['receita_liquida_centavos']) is int
assert set(answer['por_canal_centavos']) == {'loja', 'web'}
assert all(type(value) is int for value in answer['por_canal_centavos'].values())
assert answer['receita_liquida_centavos'] == 38000 == sum(answer['por_canal_centavos'].values())
